33	export function MissionListScreen({ onSelectMission }: { onSelectMission: (missionId: number) => void }) {
34	  const missionsQuery = useQuery({ queryKey: ["missions"], queryFn: api.mission.list });
35	  const [search, setSearch] = useState("");
36	  const [statusFilter, setStatusFilter] = useState<MissionStatus | "all">("all");
37	
38	  const missions = missionsQuery.data ?? EMPTY_MISSIONS;
39	
40	  const counts = useMemo(() => {
41	    const byStatus: Partial<Record<MissionStatus, number>> = {};
42	    for (const m of missions) byStatus[m.status] = (byStatus[m.status] ?? 0) + 1;
43	    return byStatus;
44	  }, [missions]);
45	
46	  const filtered = useMemo(() => {
47	    return missions.filter((m: Mission) => {
48	      if (statusFilter !== "all" && m.status !== statusFilter) return false;
49	      if (search.trim() && !m.name.toLowerCase().includes(search.trim().toLowerCase())) return false;
50	      return true;
51	    });
52	  }, [missions, statusFilter, search]);
53	
54	  return (
55	    <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-10 py-8">
56	      <div>
57	        <div className="text-[22px] font-bold">Missions</div>
58	        <div className="mt-0.5 text-[13px] text-text-2">
59	          {missionsQuery.isSuccess ? `${missions.length} mission${missions.length === 1 ? "" : "s"} in your organization` : " "}
60	        </div>
61	      </div>
62	
63	      <div className="flex flex-wrap items-center gap-2.5">
64	        <div className="relative">
65	          <svg
66	            width="15"
67	            height="15"
68	            viewBox="0 0 24 24"
69	            fill="none"
70	            stroke="var(--color-text-3)"
71	            strokeWidth="2"
72	            className="pointer-events-none absolute left-[11px] top-1/2 -translate-y-1/2"
73	          >
74	            <circle cx="11" cy="11" r="7" />
75	            <path d="M21 21l-4-4" />
76	          </svg>
77	          <input
78	            type="text"
79	            value={search}
80	            onChange={(e) => setSearch(e.target.value)}
81	            placeholder="Search missions"
82	            aria-label="Search missions"
83	            className="w-64 rounded-md border border-border bg-surface py-2.5 pl-8 pr-3 text-[13.5px] text-text placeholder:text-text-3 focus:border-accent focus:outline-none"
84	          />
85	        </div>
86	        <div className="flex-1" />
87	        <button
88	          type="button"
89	          onClick={() => setStatusFilter("all")}
90	          className={`rounded-full border px-3 py-1.5 text-[12.5px] font-medium ${
91	            statusFilter === "all" ? "border-transparent bg-accent-2 text-accent-dark" : "border-border bg-surface text-text-2"
92	          }`}
93	        >
