import { loadConfig, type AppConfig } from "@pr-review/core/config";

/**
 * The dashboard is view-only (PRD FR-19) and never uses the GitHub / Anthropic /
 * MCP secrets, but `loadConfig` requires them. We fill any missing secret with a
 * placeholder so the non-secret config (repos allow-list, `databasePath`,
 * `dashboardBaseUrl`) still loads on a box without a full `.env`. A genuinely
 * broken config file surfaces as a global banner (PRD Q23), not a crash.
 */
const PLACEHOLDER = "dashboard-view-only-unset";
const SECRET_ENV = ["GITHUB_TOKEN", "ANTHROPIC_API_KEY", "MCP_TOKEN"] as const;

export interface LoadedConfig {
  config: AppConfig | null;
  error: string | null;
}

let cached: LoadedConfig | null = null;

export function getConfig(): LoadedConfig {
  if (cached) return cached;

  const env: NodeJS.ProcessEnv = { ...process.env };
  for (const key of SECRET_ENV) {
    if (!env[key]) env[key] = PLACEHOLDER;
  }

  try {
    cached = { config: loadConfig({ env }), error: null };
  } catch (err) {
    cached = { config: null, error: err instanceof Error ? err.message : String(err) };
  }
  return cached;
}

