import { existsSync, readFileSync } from "node:fs";
import { dirname, isAbsolute, join, resolve } from "node:path";

import { config as loadDotenv } from "dotenv";
import { type ParseError, parse as parseJsonc, printParseErrorCode } from "jsonc-parser";

import { ALL_AGENTS, type AgentName, isAgentName } from "./agents";
import { ConfigError, configErrorFromZod } from "./errors";
import { envSchema, fileConfigSchema } from "./schema";
import type { AppConfig, RepoConfig } from "./types";

const CONFIG_FILENAMES = ["config.jsonc", "config.json"] as const;

export interface LoadConfigOptions {
  /** Directory to start the upward search for the config file. Default `process.cwd()`. */
  cwd?: string;
  /** Explicit config file path (absolute, or relative to `cwd`). Skips the search. */
  configPath?: string;
  /** Environment record to read secrets from. Default `process.env`. */
  env?: NodeJS.ProcessEnv;
  /** Load a local `.env` file into the environment first. Default `true`. */
  loadDotenvFile?: boolean;
}

function findConfigFile(startDir: string): string {
  let dir = resolve(startDir);
  for (;;) {
    for (const name of CONFIG_FILENAMES) {
      const candidate = join(dir, name);
      if (existsSync(candidate)) return candidate;
    }
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  throw new ConfigError(
    `no config file found (looked for ${CONFIG_FILENAMES.join(" / ")} from ${startDir} upward)`,
  );
}

function readConfigFile(path: string): unknown {
  let raw: string;
  try {
    raw = readFileSync(path, "utf8");
  } catch {
    throw new ConfigError(`config file ${path} could not be read`);
  }
  const errors: ParseError[] = [];
  const parsed = parseJsonc(raw, errors, { allowTrailingComma: true });
  const [firstError] = errors;
  if (firstError) {
    throw new ConfigError(
      `config file ${path} is not valid JSONC ` +
        `(${printParseErrorCode(firstError.error)} at offset ${firstError.offset})`,
    );
  }
  return parsed;
}

function resolveRepos(
  repos: readonly {
    owner: string;
    name: string;
    enabledAgents?: string[];
    inlineComments?: boolean;
  }[],
) {
  return repos.map((repo, index): RepoConfig => {
    // Inline review comments are on by default; a repo opts out with
    // `"inlineComments": false` (FR-21).
    const inlineComments = repo.inlineComments ?? true;

    if (repo.enabledAgents === undefined) {
      return { owner: repo.owner, name: repo.name, enabledAgents: [...ALL_AGENTS], inlineComments };
    }

    const enabledAgents: AgentName[] = [];
    for (const agent of repo.enabledAgents) {
      if (!isAgentName(agent)) {
        throw new ConfigError(`repos[${index}].enabledAgents contains unknown agent "${agent}"`);
      }
      if (!enabledAgents.includes(agent)) enabledAgents.push(agent);
    }
    if (enabledAgents.length === 0) {
      throw new ConfigError(`repos[${index}].enabledAgents must not be empty`);
    }
    return { owner: repo.owner, name: repo.name, enabledAgents, inlineComments };
  });
}

