  "pollIntervalSeconds": 180,

  // Allow-list of repos that may be reviewed (Q6). Each entry is { owner, name }.
  // Optional "enabledAgents" trims which review agents run for that repo (Q26);
  // when omitted the repo gets all five:
  //   security-code-reviewer, code-quality-reviewer, performance-reviewer,
  //   test-coverage-reviewer, documentation-accuracy-reviewer
  // Each finding that has a line and sits inside the PR diff is also posted as
  // an inline PR review comment, alongside the summary comment (FR-21). This is
  // ON by default; add "inlineComments": false to a repo entry to turn it off
  // there.
  // Example of trimming a docs-only repo and turning inline comments off:
  //   { "owner": "leslielee888888", "name": "ai-docs",
  //     "enabledAgents": ["security-code-reviewer", "documentation-accuracy-reviewer"],
